 'Business Loan':['PAN / ID proof','Address proof','Business registration / Udyam where applicable','GST registration / returns where applicable','ITR','Bank statements','Financial statements where applicable','Business vintage proof'],
 'Loan Against Property':['PAN / ID proof','Address proof','Income/business proof','Bank statements','Property ownership documents','Existing loan statement where applicable'],
