 if(type==='Home Loan')h+=`<div class="fields two"><label>Home loan purpose<select name="homePurpose"><option>Purchase - New</option><option>Purchase - Resale</option><option>Construction</option><option>Renovation / Repair</option><option>Extension</option><option>Plot + Construction</option></select></label><label>Estimated property value<input name="propertyValue" type="number" min="0" max="1000000000"></label></div>`;
 if(type==='Home Loan Balance Transfer + Top-up')h+=`<div class="fields two"><label>Current lender / bank<input name="currentLender" maxlength="100"></label><label>Current outstanding amount<input name="currentHomeOutstanding" type="number" min="0"></label><label>Current EMI<input name="currentHomeEmi" type="number" min="0"></label><label>Requested top-up amount<input name="topUpAmount" type="number" min="0"></label><label>Current home-loan tenure remaining<select name="currentHomeTenure"><option>Less than 1 year</option><option>1–3 years</option><option>3–5 years</option><option>5–10 years</option><option>10–20 years</option><option>20–30 years</option><option>30+ years</option></select></label><label>Reason for transfer<textarea name="balanceTransferReason" rows="2" maxlength="500"></textarea></label></div>`;
 if(type==='Business Loan')h+=`<div class="fields two"><label>Business type<select name="businessType" id="businessType"><option value="">Select</option><option>Trading</option><option>Manufacturing</option><option>Services</option><option>IT / Software</option><option>Retail</option><option>Wholesale</option><option>Healthcare</option><option>Education</option><option>Construction / Infrastructure</option><option>Transport / Logistics</option><option>Restaurant / Hospitality</option><option>Professional Services</option><option>E-commerce</option><option>Other</option></select></label><label>Business name<input name="businessName" maxlength="150"></label><label>Business vintage / since year<input name="businessVintage" type="number" min="1900" max="2026"></label><label>Monthly turnover<input name="monthlyTurnover" type="number" min="0"></label><label>Annual turnover<input name="annualTurnover" type="number" min="0"></label><label>Business registration type<select name="businessRegistration"><option>Proprietorship</option><option>Partnership</option><option>LLP</option><option>Private Limited</option><option>Public Limited</option><option>Trust / Society</option><option>Other</option></select></label><label>GST registered?<select name="gstRegistered"><option>Yes</option><option>No</option><option>Not applicable</option></select></label><label>Business current account?<select name="businessCurrentAccount"><option>Yes</option><option>No</option></select></label></div>`;
 if(type==='Vehicle Loan')h+=`<div class="fields two"><label>Vehicle condition *<select name="vehicleCondition" id="vehicleCondition" required><option value="">Select</option><option>New</option><option>Used</option></select></label><label>Vehicle type<select name="vehicleType"><option>Car</option><option>Two-wheeler</option><option>Commercial vehicle</option><option>Tractor / agricultural vehicle</option><option>Other</option></select></label><div id="vehicleDynamic" class="full"></div></div>`;
 if(type==='Education Loan')h+=`<div class="fields two"><label>Study country *<select name="studyCountry" id="studyCountry" required>${countryOptions()}</select></label><label>Course / programme<input name="course" required maxlength="150"></label><label>University / institution<input name="university" maxlength="200"></label><label>Intake / start date<input name="intake" maxlength="50"></label><label>Estimated education cost<input name="educationCost" type="number" min="0"></label><label>Scholarship available?<select name="scholarship"><option>Yes</option><option>No</option><option>Not sure</option></select></label><div id="educationDynamic" class="full"></div></div>`;
 if(type==='Balance Transfer / Consolidation')h+=`<div class="fields two"><label>What are you looking to transfer/consolidate?<select name="consolidationType"><option>Personal Loan</option><option>Home Loan</option><option>Credit Card / Other dues</option><option>Multiple loans / EMIs</option><option>Other</option></select></label><label>Reason for looking into balance transfer / consolidation *<select name="balanceTransferReason" required><option value="">Select</option><option>Reduce EMI burden</option><option>Review interest cost</option><option>Combine multiple EMIs into one</option><option>Need additional funds / top-up</option><option>Improve cash-flow</option><option>Other</option></select></label><label class="full">What would make the new arrangement useful to you?<textarea name="consolidationGoal" rows="3" maxlength="500"></textarea></label></div>`;
 if(type==='Personal Loan')h+=`<div class="fields two"><label>Purpose category<select name="personalPurpose"><option>Medical</option><option>Education</option><option>Wedding / family</option><option>Home improvement</option><option>Travel</option><option>Business need</option><option>Debt consolidation</option><option>Other</option></select></label><label>Required by<select name="requiredBy"><option>Immediately</option><option>Within 1 month</option><option>1–3 months</option><option>3+ months</option></select></label></div>`;
