 function toggleEmis(){const yes=document.getElementById('hasExistingEmis').value==='Yes';document.getElementById('emiCountWrap').classList.toggle('hidden',!yes);document.getElementById('emiManager').classList.toggle('hidden',!yes);if(!yes){document.getElementById('emiManager').innerHTML='';document.getElementById('totalExistingEmi').value='';document.getElementById('totalOutstandingEmi').value='';}}
 function renderEmis(){const v=document.getElementById('emiCount').value;const n=v==='11'?10:+v;const box=document.getElementById('emiManager');if(!n){box.innerHTML='';return}box.innerHTML=`<div class="emi-header"><div><h4>Existing EMI details</h4><p class="auto-note">Enter the selected EMI details. For more than 10, start with 10 and add every remaining EMI.</p></div><button type="button" class="pin-btn" id="addEmi">+ Add another EMI</button></div><div id="emiCards"></div>`;const cards=document.getElementById('emiCards');for(let i=1;i<=n;i++)cards.appendChild(makeEmiCard(i));document.getElementById('addEmi').addEventListener('click',()=>{const count=cards.children.length;if(count>=50){alert('Maximum 50 EMI entries can be added.');return}cards.appendChild(makeEmiCard(count+1));sumEmis()});cards.addEventListener('input',sumEmis);}
 function makeEmiCard(i){const d=document.createElement('div');d.className='emi-card';d.innerHTML=`<div class="emi-card-head"><h4>EMI ${i}</h4><button type="button" class="remove-emi" aria-label="Remove EMI ${i}">Remove</button></div><div class="fields two"><label>Bank / lender name *<input data-emi="bankName" maxlength="100" required></label><label>EMI per month *<input data-emi="emi" type="number" min="0" max="10000000" required></label><label>Outstanding tenure<select data-emi="tenure"><option>Less than 6 months</option><option>6–12 months</option><option>1–3 years</option><option>3–5 years</option><option>5–10 years</option><option>10–15 years</option><option>15–20 years</option><option>20–25 years</option><option>25–30 years</option><option>30+ years</option></select></label><label>Outstanding amount *<input data-emi="outstanding" type="number" min="0" max="100000000" required></label><label>Any cheque bounce in last 6 months?<select data-emi="bounce"><option>No</option><option>Yes</option><option>Not sure</option></select></label><label>Loan type *<select data-emi="loanType" required><option value="">Select</option><option>Personal Loan</option><option>Home Loan</option><option>Business Loan</option><option>Loan Against Property</option><option>Vehicle Loan</option><option>Education Loan</option><option>Credit Card</option><option>Other</option></select></label><label class="full">Additional notes for this EMI<textarea data-emi="notes" rows="2" maxlength="500"></textarea></label></div>`;d.querySelector('.remove-emi').addEventListener('click',()=>{if(document.querySelectorAll('.emi-card').length>1){d.remove();[...document.querySelectorAll('.emi-card')].forEach((c,j)=>c.querySelector('h4').textContent='EMI '+(j+1));sumEmis()}else alert('At least one EMI detail is required when existing EMIs are selected.')});return d}
 function getEmis(){return [...document.querySelectorAll('.emi-card')].map((c,i)=>({number:i+1,bankName:c.querySelector('[data-emi="bankName"]')?.value||'',emi:c.querySelector('[data-emi="emi"]')?.value||'',tenure:c.querySelector('[data-emi="tenure"]')?.value||'',outstanding:c.querySelector('[data-emi="outstanding"]')?.value||'',bounce:c.querySelector('[data-emi="bounce"]')?.value||'',loanType:c.querySelector('[data-emi="loanType"]')?.value||'',notes:c.querySelector('[data-emi="notes"]')?.value||''}))}
 function sumEmis(){const a=getEmis();document.getElementById('totalExistingEmi').value=a.reduce((x,y)=>x+(+y.emi||0),0)||'';document.getElementById('totalOutstandingEmi').value=a.reduce((x,y)=>x+(+y.outstanding||0),0)||'';}
 function renderCibil(){const v=document.getElementById('cibilIssue').value,b=document.getElementById('cibilDynamic');if(v!=='Yes'){b.innerHTML='';return}const years=Array.from({length:2026-1990+1},(_,i)=>2026-i);b.innerHTML=`<label>How many accounts have an issue? *<select name="cibilIssueCount" id="cibilIssueCount" required><option value="">Select</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select></label><div id="cibilIssues"></div>`;document.getElementById('cibilIssueCount').addEventListener('change',renderCibilIssues);}

 function renderMeeting(){const yes=document.querySelector('input[name="meetingRequired"]:checked')?.value==='Yes',b=document.getElementById('meetingDynamic');b.innerHTML=yes?`<div class="fields two"><label>Preferred mode<select name="meetingMode"><option>Google Meet</option><option>Zoom</option><option>Phone call</option><option>WhatsApp</option><option>In-person, if available</option></select></label><label>Preferred date<input name="meetingDate" id="meetingDate" type="date" min="${new Date().toISOString().slice(0,10)}"></label><label id="meetingTimeWrap" class="hidden">Preferred time<input name="meetingTime" id="meetingTime" type="time"></label></div><p class="auto-note">Phone call and WhatsApp are always available. For weekday meetings, the time is arranged by mutual understanding. Preferred time is requested only for Saturday/Sunday.</p>`:'';document.getElementById('meetingDate')?.addEventListener('change',()=>{const d=document.getElementById('meetingDate').value;if(!d)return;const day=new Date(d+'T00:00:00').getDay();document.getElementById('meetingTimeWrap').classList.toggle('hidden',![0,6].includes(day));if(![0,6].includes(day))document.getElementById('meetingTime').value='';});}
 function copyAddress(){const f=form.elements;if(document.getElementById('sameAddress').checked){['Address','Pincode','PostOffice','City','District','State'].forEach(x=>{const a=f['permanent'+x],b=f['present'+x];if(a&&b)b.value=a.value})}}
 function updateAge(){const d=new Date(document.getElementById('dob').value);if(isNaN(d)){return}const now=new Date();let age=now.getFullYear()-d.getFullYear();const m=now.getMonth()-d.getMonth();if(m<0||(m===0&&now.getDate()<d.getDate()))age--;document.getElementById('age').value=age;document.getElementById('ageText').textContent=`Current age: ${age} years`}
 async function lookupPin(target){const prefix=target==='work'?'work':target==='permanent'?'permanent':'present',pin=form.elements[prefix+'Pincode']?.value.trim();if(!/^\d{6}$/.test(pin)){alert('Please enter a valid 6-digit Indian pincode.');return}try{const r=await fetch(`https://api.postalpincode.in/pincode/${pin}`);const j=await r.json();if(!j?.[0]?.PostOffice?.length)throw new Error('Pincode not found');const po=j[0].PostOffice[0],all=j[0].PostOffice;form.elements[prefix+'PostOffice'].value=all.map(x=>x.Name).join(', ');form.elements[prefix+'City'].value=po.Block||po.District||'';form.elements[prefix+'District'].value=po.District||'';form.elements[prefix+'State'].value=po.State||'';if(target!=='work')form.elements[prefix+'Country']&&(form.elements[prefix+'Country'].value='India')}catch(e){alert('Could not fetch pincode details. Please verify the pincode or enter the address manually.')}}
