 function buildReview(){
 const f=new FormData(form),rows=[];const groups=[['Identity',['customerStatus','name','mobile','email','dob','age','gender','maritalStatus','relationToCustomer','customerNameIfDifferent']],['Addresses',['permanentAddress','permanentPincode','permanentPostOffice','permanentCity','permanentDistrict','permanentState','presentAddress','presentPincode','presentPostOffice','presentCity','presentDistrict','presentState']],['Loan & documents',['loanType','loanAmount','purpose','loanDocumentNotes']],['Work & income',['employment','monthlyIncome','annualIncome','currentAccount','companyName','currentExperience','totalExperience','pfDeduction','payslips','businessName','businessVintage','monthlyTurnover','annualTurnover','proofSinceYear','proofSinceMonth']],['Existing EMIs',['hasExistingEmis','emiCount','totalExistingEmi','totalOutstandingEmi']],['CIBIL',['cibilIssue','cibilIssueCount']],['Address proof & meeting',['addressProofs','meetingRequired','meetingMode','meetingDate','meetingTime','callbackTime','message']]];
 groups.forEach(([title,keys])=>{let h='';keys.forEach(k=>{let v=f.get(k);if(k==='addressProofs')v=[...document.querySelectorAll('input[name="addressProofs"]:checked')].map(x=>x.value).join(', ');if(k==='loanDocumentNotes')v=f.get(k);if(v)h+=`<span><b>${pretty(k)}:</b> ${escapeHtml(v)}</span>`});if(h)rows.push(`<div class="review-section"><h4>${title}</h4><div class="review-list">${h}</div><button type="button" class="edit-section btn ghost small" data-edit="${title}">Edit this section</button></div>`)});
 const emis=getEmis();if(emis.length)rows.push(`<div class="review-section"><h4>EMI details (${emis.length})</h4><div class="review-list">${emis.map(e=>`<span><b>EMI ${e.number}:</b> ${escapeHtml(e.bankName)} · ₹${escapeHtml(e.emi)} · ${escapeHtml(e.tenure)} · ₹${escapeHtml(e.outstanding)}</span>`).join('')}</div><button type="button" class="edit-section btn ghost small" data-edit="Existing EMIs">Edit this section</button></div>`);
 const cibilIssues=[...document.querySelectorAll('.issue-card')];if(cibilIssues.length)rows.push(`<div class="review-section"><h4>CIBIL issue details</h4><div class="review-list">${cibilIssues.map((c,i)=>`<span><b>Issue ${i+1}:</b> ${escapeHtml(c.querySelector('[name^="cibilIssueLoanType_"]')?.value||'')} · ${escapeHtml(c.querySelector('[name^="cibilIssueType_"]')?.value||'')} · Since ${escapeHtml(c.querySelector('[name^="cibilIssueYear_"]')?.value||'')} ${escapeHtml(c.querySelector('[name^="cibilIssueMonth_"]')?.value||'')}</span>`).join('')}</div><button type="button" class="edit-section btn ghost small" data-edit="CIBIL">Edit this section</button></div>`);
 document.getElementById('reviewBox').innerHTML=rows.join('');
 document.querySelectorAll('.edit-section').forEach(btn=>btn.addEventListener('click',()=>{const map={'Identity':2,'Addresses':2,'Loan & documents':3,'Work & income':4,'Existing EMIs':5,'CIBIL':6,'Address proof & meeting':7};const n=map[btn.dataset.edit]||1;current=n;showStep(n);}));
}
 function pretty(s){return s.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase())}
 function escapeHtml(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
 async function submitForm(e){e.preventDefault();if(!validateStep(8))return;const f=new FormData(form);f.set('emiDetailsJson',JSON.stringify(getEmis()));f.set('timestamp',new Date().toISOString());f.set('proofs',JSON.stringify([...document.querySelectorAll('input[name="proofs"]:checked')].map(x=>x.value)));f.set('loanDocuments',JSON.stringify([...document.querySelectorAll('input[name="loanDocuments"]:checked')].map(x=>x.value)));f.set('addressProofs',JSON.stringify([...document.querySelectorAll('input[name="addressProofs"]:checked')].map(x=>x.value)));f.set('propertyDetailsJson',JSON.stringify(collectPropertyFields()));const btn=form.querySelector('button[type="submit"]');btn.disabled=true;btn.textContent='Submitting…';try{if(APPS_SCRIPT_URL.includes('PASTE_YOUR'))throw new Error('Apps Script Web App URL is not configured.');const r=await fetch(APPS_SCRIPT_URL,{method:'POST',body:f});const text=await r.text();let data;try{data=JSON.parse(text)}catch(_){throw new Error('The server returned an invalid response. Check the Apps Script deployment URL and Web App access settings.')}if(!data.ok)throw new Error(data.error||'Submission failed');showSuccess(data.leadId,f)}catch(err){console.error(err);showFormError('We could not submit the enquiry right now. Your information has not been confirmed as received. Please verify the Web App deployment or email '+BUSINESS_EMAIL+'.');btn.disabled=false;btn.textContent='Submit My Enquiry →'}}
function showFormError(message){let box=document.getElementById('formError');if(!box){box=document.createElement('div');box.id='formError';box.className='form-error';form.prepend(box)}box.textContent=message;box.scrollIntoView({behavior:'smooth',block:'center'})}

 function collectPropertyFields(){const o={};['propertyType','propertyConfirmed','projectName','unitNumber','builderName','builtUpArea','houseArea','propertyAge','occupancy','plotArea','layoutAuthority','plotApproval','commercialArea','commercialOccupancy','propertyUse','propertyValue','landArea','landUse','landLocation'].forEach(k=>{if(form.elements[k])o[k]=form.elements[k].value});return o}
 function showSuccess(id,f){document.getElementById('loanForm').classList.add('hidden');const box=document.getElementById('successBox');box.classList.remove('hidden');document.getElementById('successText').innerHTML=`Your enquiry has been recorded successfully. <strong>Lead ID: ${escapeHtml(id)}</strong><br>Please send the required documents to <a href="mailto:${BUSINESS_EMAIL}">${BUSINESS_EMAIL}</a> and mention the Lead ID. We have also sent a confirmation email to ${escapeHtml(f.get('email')||'your email address')}.`;const text=`Hello Customer Fintech Solutions – New enquiry\nLead ID: ${id}\nName: ${f.get('name')||''}\nMobile: ${f.get('mobile')||''}\nLoan: ${f.get('loanType')||''}\nAmount: ${f.get('loanAmount')||''}\nEmail: ${f.get('email')||''}\nPlease contact me regarding the submitted enquiry.`;document.getElementById('whatsappCustomer').href=`https://wa.me/${BUSINESS_WHATSAPP}?text=${encodeURIComponent(text)}`;box.scrollIntoView({behavior:'smooth'})}

function initReferral(){const rf=document.getElementById('referralForm');if(!rf)return;const cat=document.getElementById('refCategory'),wrap=document.getElementById('refTypeWrap');const lists={Loans:['Personal Loan','Home Loan','Home Loan Balance Transfer + Top-up','Business Loan','Loan Against Property','Vehicle Loan','Education Loan','Balance Transfer / Consolidation','Gold Loan','Loan Against Securities','Other Loan'],Insurance:['Health Insurance','Term Insurance','Life Insurance','Personal Accident Insurance','Other Insurance'],Properties:['Buy Property','Sell Property','Residential Property','Commercial Property','Land / Plot','Other Property'], 'Documents / Registrations':['MSME / Udyam Registration','Trade Licence','Labour-related documentation','Rental / Lease Agreement','GST','ESI','PF','Employee Insurance','Other Documentation'], 'Private Finance':['Collateral-based','Non-collateral-based']};cat.addEventListener('change',()=>{const a=lists[cat.value]||[];wrap.innerHTML=a.length?`<label>${cat.value==='Private Finance'?'Finance type':'Select '+cat.value+' requirement'} *<select name="refType" required><option value="">Select</option>${a.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select></label>`:''});rf.addEventListener('submit',async e=>{e.preventDefault();let ok=true;rf.querySelectorAll('[required]').forEach(x=>{if(!x.value?.trim()&&(x.type!=='checkbox'||!x.checked)){x.classList.add('invalid');ok=false}else x.classList.remove('invalid')});const phoneOk=x=>/^[6-9]\d{9}$/.test(x.replace(/\D/g,''));['refPhone','referrerPhone'].forEach(n=>{const x=rf.elements[n];if(x&&!phoneOk(x.value)){x.classList.add('invalid');ok=false}});if(!ok)return;rf.querySelectorAll('input,select,textarea,button').forEach(x=>x.disabled=true);const payload=new FormData(rf);payload.set('action','referral');try{if(!APPS_SCRIPT_URL.includes('PASTE_YOUR')){const r=await fetch(APPS_SCRIPT_URL,{method:'POST',body:payload});const d=await r.json();if(!d.ok)console.warn('Referral was not stored:',d.error)}}catch(err){console.warn('Referral backend unavailable:',err)}document.getElementById('refThankYou').classList.remove('hidden');document.getElementById('refThankYou').scrollIntoView({behavior:'smooth',block:'center'});});}

function money(v){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(v)||0)}
